      var budget = JT.seg({ id: 'th-budget', label: T('theme.budgetQ'), value: saved.budget || 'any', options: [['free', T('theme.free')], ['low', T('theme.low')], ['any', T('theme.any')]], onChange: upd });
      var pri = JT.seg({ id: 'th-pri', label: T('theme.priQ'), value: saved.pri || 'rated', options: [['rated', T('theme.rated')], ['cheap', T('theme.cheap')], ['salla', T('theme.salla')]], onChange: upd });
      var inputs = h('div', { class: 'jt-card jt-card--in' }, [h('h2', { class: 'jt-card__t', text: T('theme.inTitle') }),
        h('div', { class: 'jt-field' }, [h('label', { class: 'jt-lab', for: 'th-cat', text: T('theme.catQ') }), h('div', { class: 'jt-selwrap' }, [catSel, h('span', { class: 'jt-how__ch', html: JT.svg('chev'), 'aria-hidden': 'true' })])]),
        budget.el, pri.el, h('p', { class: 'jt-help', text: T('theme.dataNote', { d: JT.gDate ? JT.gDate(new Date(2026, 10, 22)) : (window.JT_THEMES_DATE || '') }) })]);
      var out = h('ol', { class: 'jt-themes' });
