        return JT.makePdf('quote', { title: T('quote.pdfT'), sub: name.get(), rows: [], node: tbl, extra: [h('p', { text: T('quote.pdfNote') })], nextText: T('quote.pdfNext'), file: 'judy-quote', resT: T('quote.billT'), foot: T('quote.pdfFoot') });
