    if (host === 's.salla.sa') return { err: 'dash' };
    if (/^(mtjr\.(at|co|shop|me|site)|bit\.ly|t\.co|tinyurl\.com|wa\.me)$/.test(host)) return { err: 'short' };
    var path; try { path = decodeURIComponent(u.pathname); } catch (e) { path = u.pathname; }
